#!/usr/bin/env node
// Fails when README.md or docs/**/*.md contain AI-writing tells.
// Patterns follow the humanizer skill, based on Wikipedia's "Signs of AI writing".
// Quoted speech, blockquotes, code, and link targets are skipped.
// Usage: npm run lint:prose

import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));

// One hit fails the check. Each rule names the humanizer section it comes from.
const RULES = [
  // §1 Not X but Y
  { section: '§1', name: 'not X but Y', re: /\bnot (just|only|merely|simply) [^.!?;:]{1,80}?,? but\b/i },
  { section: '§1', name: 'it is not X, it is Y', re: /\b(it|this|that) (is|'s) not [^.!?;:,]{1,60}, (it|this|that) (is|'s) /i },
  // §2 Closers and dramatic lines
  { section: '§2', name: 'stock closer', re: /\b(let that sink in|read that again|that is the real win|that's the real win|that distinction matters)\b/i },
  // §3 Sayings that sound deep
  { section: '§3', name: 'deep-sounding saying', re: /\b(the real question is|at its core|what really matters|the heart of the matter|the deeper issue)\b/i },
  // §4 Run-up before the point
  { section: '§4', name: 'run-up', re: /\b(let's (dive|explore)|let's break (this|it) down|here's what you need to know|without further ado|let's be honest|real talk|here's the thing|the thing is)\b/i },
  // §5 Arguing with no one
  { section: '§5', name: 'rejects an unstated objection', re: /\b(this isn't (mainly )?about|i'm not saying|don't get me wrong|this is not to say|one might be tempted to|a tempting approach would be)\b/i },
  // §12 Overused AI words
  { section: '§12', name: 'overused AI word', re: /\b(delv(e|es|ed|ing)|testament|tapestry|pivotal|meticulous(ly)?|vibrant|interplay|intricacies|garner(s|ed|ing)?|showcas(e|es|ed|ing)|bolstered|enduring)\b/i },
  // §13 Inflated significance
  { section: '§13', name: 'inflated significance', re: /\b(stands as a testament|plays a key role|underscores (its|the) importance|setting the stage for|evolving landscape|indelible mark|continues to thrive|the future looks bright|exciting times ahead|a step in the right direction|challenges and legacy|future outlook|reflects a broader|enduring legacy|lasting legacy)\b/i },
  // §16 Sales language
  { section: '§16', name: 'sales language', re: /\b(nestled|in the heart of|breathtaking|must-visit|stunning|natural beauty|renowned|groundbreaking|profound)\b/i },
  // §17 Borrowed authority
  { section: '§17', name: 'unnamed authority', re: /\b(experts (believe|argue|say|agree|note)|industry reports|observers have|some critics|several publications)\b/i },
  // §18 Avoiding is, are, and has
  { section: '§18', name: 'inflated verb', re: /\b(serves as|stands as|functions as|boasts)\b/i },
  // §22 Chatbot residue
  { section: '§22', name: 'chatbot residue', re: /\b(i hope this helps|of course!|certainly!|great question|you're absolutely right|would you like me to|want me to|should i continue|let me know if|here is (an|a) (overview|summary|breakdown|list) of)\b/i },
  // §23 Knowledge-limit disclaimers and guesses
  { section: '§23', name: 'knowledge-limit disclaimer', re: /\b(up to my last (training )?update|as of my (last )?(knowledge|training)|not (publicly|extensively|widely) (available|documented|disclosed)|based on (the )?available information|it is believed that|i (don't|do not) have access to)\b/i },
  // §25 Describing the document instead of its subject
  { section: '§25', name: 'describes its own writing', re: /\b(was added to replace|flagged rather than guessed)\b/i },
];

// Weak tells. Several in one paragraph fail the check, one alone does not.
// Dashes are §8 and hedges are §9 in the humanizer skill.
const WEAK = [
  { name: 'dash', re: /[—–]/g },
  { name: 'stacked hedge', re: /\b(could potentially|might arguably|it's also possible|to be fair|it may be argued)\b/gi },
];
const WEAK_LIMIT = 3;

function markdownFiles() {
  const files = [join(root, 'README.md')];
  const docs = join(root, 'docs');
  if (existsSync(docs)) {
    for (const name of readdirSync(docs, { recursive: true })) {
      if (name.endsWith('.md')) files.push(join(docs, name));
    }
  }
  return files;
}

// Blank out the parts of one line that the rules must not read.
function maskLine(line) {
  return line
    .replace(/[‘’]/g, "'")
    .replace(/\]\([^)]*\)/g, ']()')
    .replace(/`[^`]*`/g, (m) => ' '.repeat(m.length))
    .replace(/"[^"\n]*"|“[^”\n]*”|„[^“\n]*“|«[^»\n]*»/g, (m) => ' '.repeat(m.length));
}

function lintFile(file) {
  const findings = [];
  const lines = readFileSync(file, 'utf8').split('\n');
  let inFence = false;
  let para = null;

  const flush = () => {
    if (!para) return;
    const hits = WEAK.flatMap((w) => [...para.text.matchAll(w.re)]);
    if (hits.length >= WEAK_LIMIT) {
      findings.push({ line: para.start, label: `${hits.length} dashes or stacked hedges in one paragraph (§8, §9)`, text: hits.map((h) => h[0]).join(' ') });
    }
    para = null;
  };

  lines.forEach((raw, i) => {
    const n = i + 1;
    if (/^\s*(```|~~~)/.test(raw)) {
      inFence = !inFence;
      flush();
      return;
    }
    if (inFence || /^\s*>/.test(raw)) {
      flush();
      return;
    }

    const text = maskLine(raw);
    if (!text.trim()) {
      flush();
      return;
    }

    for (const rule of RULES) {
      const m = text.match(rule.re);
      if (m) findings.push({ line: n, label: `${rule.section} ${rule.name}`, text: m[0] });
    }

    // A dash that starts a line is dialogue, not a connector.
    if (!para) para = { start: n, text: '' };
    para.text += ` ${text.replace(/^\s*[—–]/, '')}`;
  });
  flush();

  return findings;
}

const files = markdownFiles();
const findings = files.flatMap((file) => lintFile(file).map((f) => ({ ...f, file: relative(root, file) })));

for (const f of findings) {
  console.log(`${f.file}:${f.line}: ${f.label}: "${f.text}"`);
}

if (findings.length) {
  console.error(`prose lint: ${findings.length} finding(s) in ${files.length} file(s)`);
  process.exitCode = 1;
} else {
  console.log(`prose lint: ${files.length} file(s) clean`);
}

